import 'package:path/path.dart';import 'package:sqflite/sqflite.dart';import '../models/candidate_capture.dart';
class LocalDatabase{LocalDatabase._();static final instance=LocalDatabase._();Database? _db;Future<Database> get db async=>_db??=await openDatabase(join(await getDatabasesPath(),'recruitment_field.db'),version:1,onCreate:(d,_)=>d.execute('CREATE TABLE captures(id TEXT PRIMARY KEY,idempotency_key TEXT UNIQUE,name TEXT,vacancy_id TEXT,image_path TEXT,interview_score REAL,local_cv_score REAL,created_at TEXT,synced INTEGER DEFAULT 0)'));
Future<void> save(CandidateCapture c)async=>(await db).insert('captures',c.toMap(),conflictAlgorithm:ConflictAlgorithm.ignore);Future<List<CandidateCapture>> pending()async=>(await db).query('captures',where:'synced = 0',orderBy:'created_at').then((r)=>r.map(CandidateCapture.fromMap).toList());Future<void> markSynced(String id)async=>(await db).update('captures',{'synced':1},where:'id = ?',whereArgs:[id]);}
